<xf:if is="{{ $xf.visitor.hasPermission('quickSearch', 'view') }} AND {$xf.options.quickSearchShowForumList}">
<xf:css src="andy_quicksearch.less" />
<div class="block-container quicksearch">
	<div class="block-body">
		<input type="text" class="input js-filterInput" 
			aria-label="{{ phrase('quicksearch_quick_search') }}"
			autocomplete="off" 
			data-no-auto-focus="true" 
			disabled="disabled"
			id="quickSearchTitle" 
			name="quickSearchTitle" 
			onsubmit="return handle()" 
			placeholder="{{ phrase('quicksearch_quick_search...') }}" 
			style="border:none;" 
		/>
	</div>
</div>
<xf:js>
!function($, window, document, _undefined)
{
	$(document).ready(function()
	{
		var width = $(window).width();
		var pathname = '{$xf.options.boardUrl}';
		var n = pathname.charAt(pathname.length-1);		
		var keystrokeDelay = '{$xf.options.quickSearchKeystrokeDelay}';

		$("#quickSearchTitle").prop('disabled', false);

		if (n != '/')
		{
			var url = pathname + '/quicksearch';
		}
		else
		{
			var url = pathname + 'quicksearch';
		}

		$("#quickSearchTitle").keyup(delay(function (e)
		{
			currentTitle = $('#quickSearchTitle').val();
			$.ajax(
			{
				type: "POST",
				url: url,
				data: { 
					'title': currentTitle,
					_xfToken: XF.config.csrf
				},
				dataType: "html",
				timeout: 5000,
				success: function(data) 
				{
					if (width >= 600) 
					{
						$(data).find('.quicksearch-wrapper-wide').each(function()
						{
							$('#quicksearch-result').empty();
							$('#quicksearch-result').append($(this).html());
							$('#quicksearch-result').slideDown("slow");
						});
					}
					else 
					{
						$(data).find('.quicksearch-wrapper-narrow').each(function()
						{
							$('#quicksearch-result').empty();
							$('#quicksearch-result').append($(this).html());
							$('#quicksearch-result').slideDown("slow");
						});
					}
				},
				error: function(request, status, err) 
				{
					if (status != "success") {
						$('#quicksearch-result').slideUp("slow");
						$('#quicksearch-result').empty();
					}
				}
			});
		}, keystrokeDelay));
	});	
}
(jQuery, this, document);
function quickSearchClose() 
{
	$('#quicksearch-result').slideUp("slow");
	$('#quicksearch-result').empty();
	$('#quickSearchTitle').val("");
}
function delay(callback, ms) 
{
	var timer = 0;
	return function() 
	{
		var context = this, args = arguments;
		clearTimeout(timer);
		timer = setTimeout(function () 
		{
			callback.apply(context, args);
		}, ms || 0);
	};
}
</xf:js>
<div id="quicksearch-result"></div>
</xf:if>

